use comfy_table::{presets::UTF8_FULL_CONDENSED, Table};
use kiln_core::{units, CONES};

pub fn run() -> anyhow::Result<()> {
    let mut table = Table::new();
    table
        .load_preset(UTF8_FULL_CONDENSED)
        .set_header(vec!["cone", "°C", "°F"]);
    for c in CONES {
        table.add_row(vec![
            c.name.to_string(),
            c.peak_c.to_string(),
            units::c_to_f(c.peak_c).to_string(),
        ]);
    }
    println!("{table}");
    Ok(())
}

